package in.jharkhand.civic.service;
import in.jharkhand.civic.repository.JsonStore; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class RoutingEngineTest {
 @Test void ranksExpertiseAndKeepsIndustryOut(){ReferenceService ref=Mockito.mock(ReferenceService.class);JsonStore store=Mockito.mock(JsonStore.class);Mockito.when(ref.departments()).thenReturn(List.of(Map.of("id","dep-water","name","Drinking Water","category","Water","responsibilities",List.of("water","sanitation"))));Mockito.when(ref.institutions()).thenReturn(List.of(Map.of("id","inst-1","name","Water Research Institute","tier",2,"district","Ranchi","expertise",List.of("Water Management","Environmental Engineering"),"capacity","HIGH")));var engine=new RoutingEngine(ref,store);var r=engine.route(Map.of("title","Contaminated water","description","Village water issue","location",Map.of("district","Ranchi")),Map.of("domain","Water","subDomain","Quality","requiredExpertise",List.of("Water Management"),"recommendedPriority","HIGH"));assertFalse(((List<?>)r.get("departments")).isEmpty());assertFalse(((List<?>)r.get("institutions")).isEmpty());assertEquals(Boolean.FALSE,r.get("industryInvolved"));}
}
